package site.cadera.arunika.dungeon.config;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import static site.cadera.arunika.dungeon.config.SmartConfiguration.m;

/** Tests real transaction/schema code with injectable fixture codec, or real SnakeYAML when supplied. */
public final class ConfigTest {
    static int count;
    static void check(boolean b,String s){if(!b)throw new AssertionError(s);count++;System.out.println("PASS "+s);}
    interface Task {void run()throws Exception;}
    static void rejects(Task t,String name)throws Exception{try{t.run();}catch(IOException e){check(true,name);return;}throw new AssertionError(name);}
    static final class FixtureCodec implements SmartConfiguration.Codec {
        @SuppressWarnings("unchecked") public Map<String,Object> read(byte[] bytes)throws IOException{try(var in=new ObjectInputStream(new ByteArrayInputStream(bytes))){return (Map<String,Object>)in.readObject();}catch(ClassNotFoundException|ClassCastException e){throw new IOException(e);}}
        public byte[] write(Map<String,Object> data)throws IOException{var b=new ByteArrayOutputStream();try(var out=new ObjectOutputStream(b)){out.writeObject(data);}return b.toByteArray();}
    }
    static SmartConfiguration.Codec codec;
    static Map<String,Object> read(Path p)throws IOException{return codec.read(Files.readAllBytes(p));}
    static void write(Path p,Map<String,Object> m)throws IOException{Files.createDirectories(p.getParent());Files.write(p,codec.write(m));}
    public static void main(String[] args)throws Exception{
        codec=args.length>0?(SmartConfiguration.Codec)Class.forName(args[0]).getConstructor().newInstance():new FixtureCodec();
        if(args.length>0){
            var reused=List.of(m("mythicmob-id","TestMob","amount",1));
            var graph=m("first",reused,"second",reused);
            var bytes=codec.write(graph);
            check(codec.read(bytes).equals(graph),"real YAML repeated collection round trip");
            rejects(()->codec.read("first: &shared [1]\nsecond: *shared\n".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"real YAML collection aliases still rejected");
        }
        Path root=Files.createTempDirectory("adg-config-test-");try{
            var smart=new SmartConfiguration(root,codec);Path cfg=root.resolve("config.yml");write(cfg,m("schema-version",1,"scheduler",m("interval-ticks",40),"sessions",m("max-private-active",2),"unknown-admin",m("note","keep me")));byte[] v1=Files.readAllBytes(cfg);
            var s=smart.load();check(s.floors().size()==5,"five initial folders");check(s.intervalTicks()==40&&s.privateSlots()==2,"v1 custom settings retained");check(read(cfg).get("schema-version").equals(2),"schema v1 to v2");check(read(cfg).containsKey("unknown-admin"),"unknown admin keys preserved");check(Arrays.equals(v1,Files.readAllBytes(root.resolve("backups/"+s.backup()+"/original/config.yml"))),"original config byte-identical backup");
            var base=root.resolve("dungeons/01_queen_bee");Path shared=base.resolve("shared/wave-1-drops.yml"),priv=base.resolve("private/wave-1-drops.yml");check(Files.isRegularFile(shared)&&Files.isRegularFile(priv),"independent shared/private drops");check(Files.isRegularFile(base.resolve("private/boss-drops.yml")),"boss drop template");check(smart.load().changedFiles()==0,"idempotent restart; no rewrites");
            var data=read(shared);data.put("drops",m("diamond",m("type","VANILLA","material","DIAMOND","chance",2.5,"min",1,"max",4)));write(shared,data);byte[] customized=Files.readAllBytes(shared),privateOriginal=Files.readAllBytes(priv);
            var settings=read(base.resolve("settings.yml"));settings.put("wave-count",5);write(base.resolve("settings.yml"),settings);
            var next=smart.reload("queen_bee");check(next.changedFiles()==5,"wave extension writes only 4 new drop files and waves.yml");check(Files.exists(base.resolve("shared/wave-5-drops.yml")),"wave 5 created");check(Arrays.equals(customized,Files.readAllBytes(shared)),"custom drop remains byte-identical");check(Arrays.equals(privateOriginal,Files.readAllBytes(priv)),"private loot unaffected");
            settings.put("wave-count",2);write(base.resolve("settings.yml"),settings);smart.load();check(Files.exists(base.resolve("shared/wave-5-drops.yml")),"reduced waves do not delete old loot");
            var extra=smart.create("dragon",6,"Dragon King");check(extra.floors().size()==6&&extra.floors().getLast().name().equals("Dragon King"),"custom floor created");check(smart.load().floors().size()==6,"custom floor retained after restart");rejects(()->smart.create("dragon",7,"Duplicate"),"duplicate ID rejected");rejects(()->smart.create("other",6,"Duplicate"),"duplicate floor rejected");rejects(()->smart.create("../escape",9,"Escape"),"path traversal rejected");
            byte[] good=Files.readAllBytes(cfg);var bad=read(cfg);bad.put("schema-version",99);write(cfg,bad);rejects(smart::load,"future schema rejected");check(read(cfg).get("schema-version").equals(99),"future config not overwritten");Files.write(cfg,good);
            var mode=base.resolve("shared/settings.yml");byte[] modeGood=Files.readAllBytes(mode);var badMode=read(mode);badMode.put("max-players",15);write(mode,badMode);rejects(smart::load,"shared cap rejected");Files.write(mode,modeGood);
            byte[] pGood=Files.readAllBytes(priv);Files.writeString(priv,"invalid fixture: [");rejects(smart::load,"malformed or invalid config rejected");check(Files.readString(priv).equals("invalid fixture: ["),"invalid source not overwritten");Files.write(priv,pGood);
            var badDrop=read(shared);badDrop.put("drops",m("diamond",m("type","VANILLA","material","DIAMOND","chance",101,"min",1,"max",4)));write(shared,badDrop);rejects(smart::load,"invalid chance rejected");Files.write(shared,customized);
            var oldGlobal=read(cfg);oldGlobal.remove("migration");write(cfg,oldGlobal);rejects(()->smart.reload("queen_bee"),"selective reload refuses other pending migrations");smart.load();
            // Simulate interrupted commit with original and newly created file; journal recovery runs before validation.
            var tx=new ConfigTransaction(root);byte[] original=Files.readAllBytes(cfg);String id="auto-"+UUID.randomUUID();Path b=root.resolve("backups/"+id);Files.createDirectories(b.resolve("original"));Files.write(b.resolve("original/config.yml"),original);Files.writeString(b.resolve("manifest.txt"),"1 config.yml\n0 interrupted.yml");Files.writeString(root.resolve(".config-pending"),id);Files.writeString(cfg,"corrupt");Files.writeString(root.resolve("interrupted.yml"),"new");
            smart.load();check(Arrays.equals(original,Files.readAllBytes(cfg)),"interrupted transaction restored original");check(!Files.exists(root.resolve("interrupted.yml"))&&!Files.exists(root.resolve(".config-pending")),"interrupted transaction removed new file and marker");
            // Induce write failure after one write; nonempty destination is unreplaceable. Rollback stays recoverable for failed rollback.
            byte[] before=Files.readAllBytes(cfg);try{tx.locked(()->{var change=new LinkedHashMap<String,byte[]>();change.put("config.yml","changed".getBytes());change.put("missing-parent/file.yml","x".getBytes());return tx.commit(change);});throw new AssertionError("unmanaged file accepted");}catch(IOException e){check(Arrays.equals(before,Files.readAllBytes(cfg)),"unmanaged plan refused before original write");}
            var failPlan=new LinkedHashMap<String,byte[]>();failPlan.put("config.yml","temporary bad bytes".getBytes());failPlan.put("new-file.yml","new".getBytes());
            rejects(()->tx.locked(()->tx.commit(failPlan,(path,bytes)->{if(path.getFileName().toString().equals("new-file.yml"))throw new IOException("Injected failure");ConfigTransaction.atomic(path,bytes); })),"injected commit failure");
            check(Arrays.equals(before,Files.readAllBytes(cfg))&&!Files.exists(root.resolve("new-file.yml"))&&!Files.exists(root.resolve(".config-pending")),"immediate rollback restores originals and clears journal");
            // v0.3 additive migration from existing schema-2 config without battle fields.
            var oldConfig=read(cfg);oldConfig.remove("battle-preview");oldConfig.remove("battle-tick-interval");write(cfg,oldConfig);Path battle=base.resolve("battle.yml");Files.delete(battle);var migrated=smart.load();check(!migrated.battlePreview()&&migrated.battles().isEmpty()&&Files.exists(battle),"v0.2 config receives disabled battle template");check(Arrays.equals(customized,Files.readAllBytes(shared)),"battle migration preserves custom drop bytes");
            var w=read(base.resolve("waves.yml"));w.put("waves",m("wave-1",m("mobs",List.of(m("mythicmob-id","TestBee","amount",3))),"wave-2",m("mobs",List.of(m("mythicmob-id","TestElite","amount",1)))));write(base.resolve("waves.yml"),w);var bossConfig=read(base.resolve("boss.yml"));bossConfig.put("mythicmob-id","TestBoss");write(base.resolve("boss.yml"),bossConfig);
            var location=m("world","test","x",5,"y",65,"z",5);var min=m("world","test","x",0,"y",60,"z",0);var max=m("world","test","x",20,"y",80,"z",20);var exit=m("world","test","x",100,"y",65,"z",100);
            var arena=m("id","shared_1","mode","SHARED","bounds",m("min",min,"max",max),"player-spawn",location,"mob-spawns",List.of(location),"boss-spawn",location,"exit",exit);
            var battleConfig=read(battle);battleConfig.put("enabled",true);battleConfig.put("arenas",List.of(arena));write(battle,battleConfig);var parsed=smart.load();check(parsed.battles().get("queen_bee").waves().size()==2&&parsed.battles().get("queen_bee").boss().equals("TestBoss"),"battle snapshot parses existing wave and boss config");check(!parsed.battlePreview(),"floor enable cannot activate public preview");
            check(!parsed.sharedPreview()&&parsed.sharedCountdowns().get("queen_bee")==30,"shared default off; configured floor countdown loaded");
            var shconfig=read(mode);shconfig.put("queue-countdown-seconds",45);write(mode,shconfig);check(smart.load().sharedCountdowns().get("queen_bee")==45,"custom floor countdown preserved");
            shconfig.put("enabled",false);write(mode,shconfig);check(!smart.load().sharedCountdowns().containsKey("queen_bee"),"disabled Shared mode excluded");shconfig.put("enabled",true);write(mode,shconfig);
            var globals=read(cfg);globals.remove("shared-preview");write(cfg,globals);check(!smart.load().sharedPreview(),"v0.3 config receives disabled shared-preview");globals=read(cfg);globals.put("shared-preview",true);write(cfg,globals);rejects(smart::load,"shared-preview requires battle-preview");globals.put("battle-preview",true);write(cfg,globals);check(smart.load().sharedPreview(),"explicit dual preview enables staging config");globals.put("shared-preview",false);globals.put("battle-preview",false);write(cfg,globals);smart.load();
            globals=read(cfg);globals.remove("private-preview");write(cfg,globals);check(!smart.load().privatePreview(),"v0.4 config gains disabled private preview");
            globals=read(cfg);globals.put("private-preview",true);write(cfg,globals);rejects(smart::load,"private preview needs battle preview");globals.put("battle-preview",true);write(cfg,globals);
            var pLoc=m("world","test","x",45,"y",65,"z",45);var pMin=m("world","test","x",40,"y",60,"z",40);var pMax=m("world","test","x",60,"y",80,"z",60);
            var pArena=m("id","private_1","mode","PRIVATE","bounds",m("min",pMin,"max",pMax),"player-spawn",pLoc,"mob-spawns",List.of(pLoc),"boss-spawn",pLoc,"exit",exit);battleConfig.put("arenas",List.of(arena,pArena));write(battle,battleConfig);
            Path pSettings=base.resolve("private/settings.yml");var pConfig=read(pSettings);pConfig.put("max-players",3);write(pSettings,pConfig);var privateParsed=smart.load();check(privateParsed.privatePreview()&&privateParsed.privateLimits().get("queen_bee")==3,"private mode limit honored");check(privateParsed.ticketMaterial().equals("PAPER"),"universal ticket material preserved");pConfig.put("enabled",false);write(pSettings,pConfig);check(!smart.load().privateLimits().containsKey("queen_bee"),"disabled Private mode excluded");pConfig.put("enabled",true);write(pSettings,pConfig);globals.put("private-preview",false);globals.put("battle-preview",false);write(cfg,globals);smart.load();
            arena.put("boss-spawn",exit);battleConfig.put("arenas",List.of(arena));write(battle,battleConfig);rejects(smart::load,"invalid boss location rejected before commit");arena.put("boss-spawn",location);battleConfig.put("enabled",false);battleConfig.put("arenas",List.of(arena));write(battle,battleConfig);smart.load();
            var oldLoot=read(cfg);oldLoot.remove("loot-preview");write(cfg,oldLoot);var perfPath=root.resolve("performance.yml");var oldPerf=read(perfPath);oldPerf.remove("max-active-loot-items");write(perfPath,oldPerf);var lootSnapshot=smart.load();check(!lootSnapshot.lootPreview()&&lootSnapshot.lootBudget()==256,"v0.5 migration disables loot preview and sets entity budget");
            var lootPlan=lootSnapshot.lootPlans().get("queen_bee:shared");check(lootPlan.waves().get(1).entries().getFirst().chance()==2.5&&lootSnapshot.lootPlans().get("queen_bee:private").waves().get(1).entries().isEmpty(),"independent configured loot parsed into immutable plans");
            var edited=smart.editDrop("queen_bee","private","boss","custom",m("type","SERIALIZED","id","YQ==","chance",100,"min",1,"max",2));check(Files.exists(root.resolve("backups/"+edited+"/original/dungeons/01_queen_bee/private/boss-drops.yml")),"editor automatic backup");check(smart.load().lootPlans().get("queen_bee:private").boss().entries().size()==1,"editor saved independent table");
            byte[] editedBytes=Files.readAllBytes(base.resolve("private/boss-drops.yml"));rejects(()->smart.editDrop("queen_bee","private","boss","bad",m("type","VANILLA","material","STONE","chance",-1,"min",1,"max",1)),"editor rejects invalid chance");check(Arrays.equals(editedBytes,Files.readAllBytes(base.resolve("private/boss-drops.yml"))),"bad editor input does not overwrite table");smart.editDrop("queen_bee","private","boss","custom",null);check(smart.load().lootPlans().get("queen_bee:private").boss().entries().isEmpty(),"editor remove persists");rejects(()->smart.editDrop("../escape","private","boss","custom",null),"editor traversal rejected");
            var badLoot=read(cfg);badLoot.put("loot-preview",true);write(cfg,badLoot);rejects(smart::load,"loot-preview requires battle-preview");badLoot.put("loot-preview",false);write(cfg,badLoot);smart.load();
            Path gatePath=root.resolve("integrations/waystone.yml");var gate=read(gatePath);gate.remove("return-waystones");gate.remove("interaction-radius");gate.put("custom-note","keep");write(gatePath,gate);var gateDefault=smart.load();check(!gateDefault.gateway().enabled()&&gateDefault.gateway().radius()==6,"v0.7 gateway config migrated disabled");check(read(gatePath).get("custom-note").equals("keep"),"gateway migration preserves admin keys");
            gate=read(gatePath);gate.put("enabled",true);write(gatePath,gate);rejects(smart::load,"incomplete enabled gateway refused");
            gate.put("gateway-id",UUID.randomUUID().toString());gate.put("hub",exit);write(gatePath,gate);rejects(smart::load,"gateway requires battle preview and arena");
            var current=read(cfg);current.put("battle-preview",true);write(cfg,current);battleConfig.put("enabled",true);battleConfig.put("arenas",List.of(arena));write(battle,battleConfig);var activeGateway=smart.load();check(activeGateway.gateway().enabled()&&activeGateway.gateway().hub().world().equals("test"),"valid gateway and exact hub exit loaded");
            var stone=UUID.randomUUID().toString();gate.put("return-waystones",m(stone,"queen_bee/shared_1"));write(gatePath,gate);check(smart.load().gateway().returns().size()==1,"return Waystone binding preserved");
            gate.put("return-waystones",m(stone,"queen_bee/unknown"));write(gatePath,gate);rejects(smart::load,"unknown return arena rejected");gate.put("return-waystones",m(gate.get("gateway-id"),"queen_bee/shared_1"));write(gatePath,gate);rejects(smart::load,"hub cannot also be return stone");
            gate.put("return-waystones",m());gate.put("hub",location);write(gatePath,gate);rejects(smart::load,"hub inside arena rejected");gate.put("hub",m("world","test","x",101,"y",65,"z",100));write(gatePath,gate);rejects(smart::load,"arena exit different from hub rejected");
            gate.put("enabled",false);gate.put("hub",exit);write(gatePath,gate);current.put("battle-preview",false);write(cfg,current);battleConfig.put("enabled",false);write(battle,battleConfig);smart.load();
            // Backup retention only prunes owned directories, never legacy imports.
            Path manual=root.resolve("backups/legacy-001");Files.createDirectories(manual);for(int i=7;i<=12;i++)smart.create("extra_"+i,i,"Extra "+i);try(var stream=Files.list(root.resolve("backups"))){check(stream.filter(p->p.getFileName().toString().startsWith("auto-")&&Files.exists(p.resolve("manifest.txt"))).count()<=5,"automatic retention max five");}check(Files.isDirectory(manual),"legacy backup not pruned");
            try{Path link=root.resolve("messages.yml");Files.delete(link);Files.createSymbolicLink(link,cfg);rejects(smart::load,"symlink configuration refused");}catch(UnsupportedOperationException|FileSystemException skipped){System.out.println("SKIP symlink unsupported");}
            if(args.length>0){rejects(()->codec.read("duplicate: 1\nduplicate: 2\n".getBytes()),"duplicate YAML keys rejected");rejects(()->codec.read("x: !!java.net.URL [http://example.com]".getBytes()),"unsafe YAML tag rejected");}
            System.out.println("TOTAL "+count+" PASS ("+codec.getClass().getSimpleName()+")");
        }finally{try(var walk=Files.walk(root)){for(Path p:walk.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}
    }
}
